  const [settings,setSettings]=useState<Settings>(baseInitial);const [pattern,setPatternState]=useState<Pattern>(initialPattern);const [surface,setSurfaceState]=useState<Surface>("plane");const [shape,setShapeState]=useState<Shape>("circle");const [orient,setOrientState]=useState<Orient>("fixed");const [mode,setModeState]=useState<Mode>("repel");const [logo,setLogoState]=useState<LogoPreset>(initialLogo);const [palette,setPaletteState]=useState<Palette>(initialPalette);const [relations,setRelationsState]=useState<Relations>(initialRelations);const [relationSystem,setRelationSystemState]=useState<RelationSystem>(initialRelationSystem);const [panel,setPanel]=useState(true);const [recording,setRecording]=useState(false);
  const set=useCallback(<K extends keyof Settings>(key:K,value:Settings[K])=>setSettings(old=>{const next={...old,[key]:value};settingsRef.current=next;return next}),[]);
  const rebuild=()=>window.dispatchEvent(new Event("dotwise:rebuild"));
