    const defaults:Record<Exclude<Pattern,"logo">,number>={ring:9,spiral:18,phyllotaxis:24,grid:16,hex:19,arc:9};
    const current=settingsRef.current;
    const expanding=v!=="logo"&&current.count<2;
    const next={...current,radius:current.radius<20?220:current.radius,count:expanding?defaults[v]:current.count,dotSize:expanding&&current.dotSize>28?26:current.dotSize};
