  const setRelations=(next:Relations)=>{relationsRef.current=next;setRelationsState(next)};
  const setRelationSystem=(next:RelationSystem)=>{relationSystemRef.current=next;setRelationSystemState(next)};
  const chooseGradient=(id:GradientId)=>{const preset=gradientPresets.find(item=>item.id===id)!;setPalette({...paletteRef.current,mode:"gradient",preset:id,from:preset.from,to:preset.to})};
  const download=(name:string,blob:Blob)=>{const url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=name;a.style.display="none";document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)};
  const exportPNG=()=>canvasRef.current?.toBlob(blob=>blob&&download("dotwise.png",blob),"image/png");
