        if(k==="orbit")[[0,-.34],[.34,0],[0,.34],[-.34,0]].forEach(([x,y],i)=>list.push({x:x*r,y:y*r,angle:i*Math.PI/2}));
        if(k==="petals")[[0,-.34],[.34,0],[0,.34],[-.34,0]].forEach(([x,y],i)=>list.push({x:x*r,y:y*r,angle:i*Math.PI/2}));
